python3 << 'PYEOF'
exec(open('make_preds.py').read())
import csv
with open('market.csv') as f:
    all_qids = set(r['qid'] for r in csv.DictReader(f))
predicted = set(P.keys())
missing = all_qids - predicted
print("MISSING qids:", missing)
for m in missing:
    import csv
    with open('market.csv') as f:
        for r in csv.DictReader(f):
            if r['qid']==m:
                print("  ", m, "-", r['title'][:120], "| res", r['resolution_date'])

# Validate entries
print("\n=== VALIDATION ===")
issues=[]
for qid, d in P.items():
    if not d: issues.append((qid,"EMPTY"))
    for k,v in d.items():
        if v==0 or v<=0: issues.append((qid,f"zero/neg prob {k}={v}"))
    s=sum(d.values())
    if s>1.0+1e-9: issues.append((qid,f"sum {s:.3f} >1"))
    if len(d)>5: issues.append((qid,f"{len(d)} outcomes >5"))
print(f"Issues found: {len(issues)}")
for i in issues[:40]:
    print("  ", i)
PYEOF

